use std::fmt;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Difficulty {
    Easy,
    Moderate,
    Hard,
}

impl fmt::Display for Difficulty {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(match self {
            Self::Easy => "easy",
            Self::Moderate => "moderate",
            Self::Hard => "hard",
        })
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Route {
    pub name: &'static str,
    pub distance_km: f64,
    pub difficulty: Difficulty,
}

pub fn catalogue() -> Vec<Route> {
    vec![
        Route {
            name: "Fern Loop",
            distance_km: 3.2,
            difficulty: Difficulty::Easy,
        },
        Route {
            name: "North Ridge",
            distance_km: 11.5,
            difficulty: Difficulty::Hard,
        },
        Route {
            name: "Lake Circuit",
            distance_km: 7.0,
            difficulty: Difficulty::Moderate,
        },
        Route {
            name: "Fern Valley",
            distance_km: 8.5,
            difficulty: Difficulty::Moderate,
        },
        Route {
            name: "Summit Traverse",
            distance_km: 16.0,
            difficulty: Difficulty::Hard,
        },
    ]
}

pub fn display_route(route: &Route) -> String {
    format!(
        "{} | {:.1} km | {}",
        route.name, route.distance_km, route.difficulty
    )
}

/// Composable route filter; unset criteria match everything.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct SearchFilter {
    name_contains: Option<String>,
    max_distance_km: Option<f64>,
    difficulty: Option<Difficulty>,
}

impl SearchFilter {
    pub fn new() -> Self {
        Self::default()
    }

    /// Case-insensitive name substring. An empty string matches every name.
    pub fn name_contains(mut self, text: impl Into<String>) -> Self {
        self.name_contains = Some(text.into().to_lowercase());
        self
    }

    /// Inclusive maximum distance. NaN or negative values match no routes.
    pub fn max_distance_km(mut self, km: f64) -> Self {
        self.max_distance_km = Some(km);
        self
    }

    pub fn difficulty(mut self, difficulty: Difficulty) -> Self {
        self.difficulty = Some(difficulty);
        self
    }

    pub fn matches(&self, route: &Route) -> bool {
        self.name_contains
            .as_ref()
            .is_none_or(|text| route.name.to_lowercase().contains(text.as_str()))
            && self
                .max_distance_km
                .is_none_or(|max| route.distance_km <= max)
            && self.difficulty.is_none_or(|d| route.difficulty == d)
    }
}

/// Returns matching routes borrowed from `routes`, in their original order.
pub fn search<'a>(routes: &'a [Route], filter: &SearchFilter) -> Vec<&'a Route> {
    routes
        .iter()
        .filter(|route| filter.matches(route))
        .collect()
}

/// Reason a route set could not be exported as JSON.
#[derive(Clone, Debug, PartialEq)]
pub enum ExportError {
    /// The route's distance is NaN or infinite.
    NonFiniteDistance { name: String },
    /// The route's distance is below zero.
    NegativeDistance { name: String, distance_km: f64 },
}

impl fmt::Display for ExportError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NonFiniteDistance { name } => {
                write!(formatter, "route {name:?} has a non-finite distance")
            }
            Self::NegativeDistance { name, distance_km } => {
                write!(
                    formatter,
                    "route {name:?} has a negative distance ({distance_km})"
                )
            }
        }
    }
}

impl std::error::Error for ExportError {}

fn push_json_string(out: &mut String, text: &str) {
    out.push('"');
    for ch in text.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if c < '\u{20}' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Exports routes as a compact JSON array with `name`, `distance_km` and
/// `difficulty` keys, preserving input order. Fails before producing any
/// output if a distance is non-finite or negative.
pub fn export_json(routes: &[&Route]) -> Result<String, ExportError> {
    let mut out = String::from("[");
    for (index, route) in routes.iter().enumerate() {
        let distance = route.distance_km;
        if !distance.is_finite() {
            return Err(ExportError::NonFiniteDistance {
                name: route.name.to_owned(),
            });
        }
        if distance < 0.0 {
            return Err(ExportError::NegativeDistance {
                name: route.name.to_owned(),
                distance_km: distance,
            });
        }
        if index > 0 {
            out.push(',');
        }
        out.push_str("{\"name\":");
        push_json_string(&mut out, route.name);
        // Adding 0.0 normalises -0.0 to 0.0.
        out.push_str(&format!(",\"distance_km\":{}", distance + 0.0));
        out.push_str(",\"difficulty\":");
        push_json_string(&mut out, &route.difficulty.to_string());
        out.push('}');
    }
    out.push(']');
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn names(found: &[&Route]) -> Vec<&'static str> {
        found.iter().map(|route| route.name).collect()
    }

    #[test]
    fn empty_filter_returns_all_in_order() {
        let routes = catalogue();
        let found = search(&routes, &SearchFilter::new());
        assert_eq!(found.len(), routes.len());
        assert!(found.iter().zip(&routes).all(|(a, b)| std::ptr::eq(*a, b)));
    }

    #[test]
    fn name_is_case_insensitive_substring() {
        let routes = catalogue();
        let found = search(&routes, &SearchFilter::new().name_contains("FERN"));
        assert_eq!(names(&found), ["Fern Loop", "Fern Valley"]);
    }

    #[test]
    fn max_distance_is_inclusive() {
        let routes = catalogue();
        let found = search(&routes, &SearchFilter::new().max_distance_km(8.5));
        assert_eq!(names(&found), ["Fern Loop", "Lake Circuit", "Fern Valley"]);
    }

    #[test]
    fn difficulty_filters() {
        let routes = catalogue();
        let found = search(&routes, &SearchFilter::new().difficulty(Difficulty::Hard));
        assert_eq!(names(&found), ["North Ridge", "Summit Traverse"]);
    }

    #[test]
    fn combined_filters_all_apply() {
        let routes = catalogue();
        let filter = SearchFilter::new()
            .name_contains("fern")
            .max_distance_km(8.5)
            .difficulty(Difficulty::Moderate);
        assert_eq!(names(&search(&routes, &filter)), ["Fern Valley"]);
        let none = filter.max_distance_km(8.4);
        assert!(search(&routes, &none).is_empty());
    }

    #[test]
    fn invalid_distances_match_nothing() {
        let routes = catalogue();
        assert!(search(&routes, &SearchFilter::new().max_distance_km(f64::NAN)).is_empty());
        assert!(search(&routes, &SearchFilter::new().max_distance_km(-1.0)).is_empty());
    }

    #[test]
    fn catalogue_is_small_and_deterministic() {
        assert_eq!(catalogue().len(), 5);
        assert_eq!(catalogue()[0].name, "Fern Loop");
    }

    #[test]
    fn route_display_is_readable() {
        assert_eq!(display_route(&catalogue()[0]), "Fern Loop | 3.2 km | easy");
    }

    fn route(name: &'static str, distance_km: f64) -> Route {
        Route {
            name,
            distance_km,
            difficulty: Difficulty::Easy,
        }
    }

    #[test]
    fn exports_catalogue() {
        let routes = catalogue();
        let refs: Vec<&Route> = routes.iter().collect();
        assert_eq!(
            export_json(&refs).unwrap(),
            concat!(
                r#"[{"name":"Fern Loop","distance_km":3.2,"difficulty":"easy"},"#,
                r#"{"name":"North Ridge","distance_km":11.5,"difficulty":"hard"},"#,
                r#"{"name":"Lake Circuit","distance_km":7,"difficulty":"moderate"},"#,
                r#"{"name":"Fern Valley","distance_km":8.5,"difficulty":"moderate"},"#,
                r#"{"name":"Summit Traverse","distance_km":16,"difficulty":"hard"}]"#
            )
        );
    }

    #[test]
    fn exports_empty_selection() {
        assert_eq!(export_json(&[]).unwrap(), "[]");
    }

    #[test]
    fn escapes_special_and_control_characters() {
        let r = route("a\"b\\c\td\re\nf\u{08}\u{0c}\u{01}\u{1f}é🌲", -0.0);
        let json = export_json(&[&r]).unwrap();
        assert_eq!(
            json,
            r#"[{"name":"a\"b\\c\td\re\nf\b\f\u0001\u001fé🌲","distance_km":0,"difficulty":"easy"}]"#
        );
    }

    #[test]
    fn rejects_nonfinite_distances() {
        for value in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
            let r = route("Bad", value);
            let err = export_json(&[&r]).unwrap_err();
            assert_eq!(err, ExportError::NonFiniteDistance { name: "Bad".into() });
            assert!(err.to_string().contains("non-finite"));
        }
    }

    #[test]
    fn rejects_negative_distance() {
        let good = route("Good", 1.0);
        let bad = route("Bad", -0.5);
        let err = export_json(&[&good, &bad]).unwrap_err();
        assert_eq!(
            err,
            ExportError::NegativeDistance {
                name: "Bad".into(),
                distance_km: -0.5
            }
        );
        let _: &dyn std::error::Error = &err;
        assert!(err.to_string().contains("negative"));
    }
}
use routebook::{
    Difficulty, ExportError, Route, SearchFilter, catalogue, display_route, export_json, search,
};

const USAGE: &str = "Usage:\n  routebook list\n  routebook search [--name TEXT] [--max-distance KM] [--difficulty easy|moderate|hard]\n  routebook export [--name TEXT] [--max-distance KM] [--difficulty easy|moderate|hard]";

fn parse_difficulty(value: &str) -> Result<Difficulty, String> {
    match value.to_ascii_lowercase().as_str() {
        "easy" => Ok(Difficulty::Easy),
        "moderate" => Ok(Difficulty::Moderate),
        "hard" => Ok(Difficulty::Hard),
        _ => Err(format!(
            "invalid difficulty '{value}': expected easy, moderate or hard"
        )),
    }
}

fn parse_distance(value: &str) -> Result<f64, String> {
    match value.parse::<f64>() {
        Ok(km) if km.is_finite() && km >= 0.0 => Ok(km),
        _ => Err(format!(
            "invalid --max-distance '{value}': expected a non-negative number of kilometers"
        )),
    }
}

fn parse_search_args(args: &[String]) -> Result<SearchFilter, String> {
    let mut filter = SearchFilter::new();
    let (mut name, mut distance, mut difficulty) = (false, false, false);
    let mut iter = args.iter().peekable();
    while let Some(flag) = iter.next() {
        let seen = match flag.as_str() {
            "--name" => &mut name,
            "--max-distance" => &mut distance,
            "--difficulty" => &mut difficulty,
            other => return Err(format!("unknown argument '{other}'")),
        };
        if *seen {
            return Err(format!("{flag} was given more than once"));
        }
        *seen = true;
        let value = iter
            .next_if(|next| !matches!(next.as_str(), "--name" | "--max-distance" | "--difficulty"))
            .ok_or_else(|| format!("{flag} requires a value"))?;
        filter = match flag.as_str() {
            "--name" => filter.name_contains(value.as_str()),
            "--max-distance" => filter.max_distance_km(parse_distance(value)?),
            _ => filter.difficulty(parse_difficulty(value)?),
        };
    }
    Ok(filter)
}

fn fail(message: &str) -> ! {
    eprintln!("error: {message}\n{USAGE}");
    std::process::exit(2);
}

fn export_matches(routes: &[Route], filter: &SearchFilter) -> Result<String, ExportError> {
    export_json(&search(routes, filter))
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.split_first() {
        Some((command, rest)) if command == "list" && rest.is_empty() => {
            for route in catalogue() {
                println!("{}", display_route(&route));
            }
        }
        Some((command, rest)) if command == "search" => {
            let filter = parse_search_args(rest).unwrap_or_else(|message| fail(&message));
            let routes = catalogue();
            for route in search(&routes, &filter) {
                println!("{}", display_route(route));
            }
        }
        Some((command, rest)) if command == "export" => {
            let filter = parse_search_args(rest).unwrap_or_else(|message| fail(&message));
            match export_matches(&catalogue(), &filter) {
                Ok(json) => println!("{json}"),
                Err(error) => {
                    eprintln!("error: export failed: {error}");
                    std::process::exit(1);
                }
            }
        }
        Some((command, _)) if command == "list" => fail("list takes no arguments"),
        Some((command, _)) => fail(&format!("unknown command '{command}'")),
        None => fail("missing command"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(args: &[&str]) -> Result<SearchFilter, String> {
        let args: Vec<String> = args.iter().map(|s| s.to_string()).collect();
        parse_search_args(&args)
    }

    #[test]
    fn export_reports_serialization_errors() {
        let bad = Route {
            name: "Bad",
            distance_km: f64::NAN,
            difficulty: Difficulty::Easy,
        };
        let err = export_matches(&[bad], &SearchFilter::new()).unwrap_err();
        assert!(matches!(err, ExportError::NonFiniteDistance { .. }));
    }

    #[test]
    fn parses_combined_flags() {
        let expected = SearchFilter::new()
            .name_contains("fern")
            .max_distance_km(8.5)
            .difficulty(Difficulty::Moderate);
        let parsed = parse(&[
            "--difficulty",
            "Moderate",
            "--name",
            "fern",
            "--max-distance",
            "8.5",
        ]);
        assert_eq!(parsed, Ok(expected));
    }

    #[test]
    fn rejects_bad_input() {
        for args in [
            &["--max-distance", "abc"][..],
            &["--max-distance", "-1"],
            &["--max-distance", "NaN"],
            &["--difficulty", "extreme"],
            &["--name"],
            &["--name", "--difficulty", "easy"],
            &["--name", "a", "--name", "b"],
            &["--bogus", "x"],
            &["fern"],
        ] {
            assert!(parse(args).is_err(), "{args:?} should be rejected");
        }
    }
}
use std::process::{Command, Output};

const FERN_LOOP: &str = r#"{"name":"Fern Loop","distance_km":3.2,"difficulty":"easy"}"#;
const NORTH_RIDGE: &str = r#"{"name":"North Ridge","distance_km":11.5,"difficulty":"hard"}"#;
const LAKE_CIRCUIT: &str = r#"{"name":"Lake Circuit","distance_km":7,"difficulty":"moderate"}"#;
const FERN_VALLEY: &str = r#"{"name":"Fern Valley","distance_km":8.5,"difficulty":"moderate"}"#;
const SUMMIT: &str = r#"{"name":"Summit Traverse","distance_km":16,"difficulty":"hard"}"#;

fn run(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_routebook"))
        .args(args)
        .output()
        .expect("failed to run routebook")
}

fn assert_export(args: &[&str], expected: &[&str]) {
    let out = run(args);
    let want = format!("[{}]\n", expected.join(","));
    assert_eq!(out.status.code(), Some(0), "args {args:?}");
    assert_eq!(String::from_utf8_lossy(&out.stdout), want, "args {args:?}");
    assert_eq!(String::from_utf8_lossy(&out.stderr), "", "args {args:?}");
}

fn assert_export_usage_error(args: &[&str]) {
    let out = run(args);
    assert_eq!(out.status.code(), Some(2), "args {args:?}");
    assert_eq!(String::from_utf8_lossy(&out.stdout), "", "args {args:?}");
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(err.starts_with("error: "), "args {args:?}: {err:?}");
    assert!(err.contains("Usage:"), "args {args:?}: {err:?}");
}

#[test]
fn unfiltered_export_is_one_array_in_catalogue_order() {
    assert_export(
        &["export"],
        &[FERN_LOOP, NORTH_RIDGE, LAKE_CIRCUIT, FERN_VALLEY, SUMMIT],
    );
}

#[test]
fn filtered_exports_match_search_semantics() {
    assert_export(&["export", "--name", "FERN"], &[FERN_LOOP, FERN_VALLEY]);
    assert_export(
        &["export", "--max-distance", "8.5"],
        &[FERN_LOOP, LAKE_CIRCUIT, FERN_VALLEY],
    );
    assert_export(&["export", "--difficulty", "Hard"], &[NORTH_RIDGE, SUMMIT]);
    assert_export(
        &[
            "export",
            "--difficulty",
            "moderate",
            "--max-distance",
            "8.5",
            "--name",
            "fern",
        ],
        &[FERN_VALLEY],
    );
}

#[test]
fn empty_export_prints_empty_array_and_succeeds() {
    assert_export(&["export", "--name", "nonexistent"], &[]);
    assert_export(&["export", "--max-distance", "0"], &[]);
}

#[test]
fn export_output_is_valid_single_line_json_array() {
    let out = run(&["export"]);
    let text = String::from_utf8(out.stdout).unwrap();
    assert!(text.starts_with('[') && text.ends_with("]\n"));
    assert_eq!(text.matches('\n').count(), 1);
}

#[test]
fn export_parse_errors_exit_2_with_stderr() {
    for args in [
        &["export", "--max-distance", "abc"][..],
        &["export", "--max-distance", "-1"],
        &["export", "--difficulty", "extreme"],
        &["export", "--name"],
        &["export", "--name", "a", "--name", "b"],
        &["export", "--bogus"],
        &["export", "fern"],
    ] {
        assert_export_usage_error(args);
    }
}

#[test]
fn export_error_message_names_flag_and_value() {
    let out = run(&["export", "--max-distance", "abc"]);
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(
        err.starts_with("error: invalid --max-distance 'abc'"),
        "{err:?}"
    );
}

#[test]
fn list_and_search_output_is_unchanged() {
    let list = run(&["list"]);
    let search = run(&["search"]);
    let expected = "Fern Loop | 3.2 km | easy\nNorth Ridge | 11.5 km | hard\nLake Circuit | 7.0 km | moderate\nFern Valley | 8.5 km | moderate\nSummit Traverse | 16.0 km | hard\n";
    for out in [&list, &search] {
        assert_eq!(out.status.code(), Some(0));
        assert_eq!(String::from_utf8_lossy(&out.stdout), expected);
        assert!(out.stderr.is_empty());
    }
    let filtered = run(&["search", "--difficulty", "easy"]);
    assert_eq!(
        String::from_utf8_lossy(&filtered.stdout),
        "Fern Loop | 3.2 km | easy\n"
    );
}
